import React from 'react';
import Button from '../../components/Button';

const SsoOptions = () => {
    return (
        <>
            <div className="relative flex items-center py-2">
                <div className="flex-grow border-t border-outline-variant"></div>
                <span className="flex-shrink mx-4 font-label-sm text-label-sm text-on-surface-variant">OR MORE</span>
                <div className="flex-grow border-t border-outline-variant"></div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <Button className="flex items-center justify-center h-12 border border-outline-variant rounded-lg hover:bg-surface-container-low transition-colors font-label-sm text-label-sm text-on-surface gap-2" type="button" text="Google" icon="g_mobiledata_bad">
                    {/* <span className="material-symbols-outlined" style={{ fontSize: '20px' }}>Google</span> */}
                    <span class="material-symbols-outlined">
                        g_mobiledata_badge
                    </span>
                    <span className='text-[15px]'>Google</span>
                </Button>
                <Button className="flex items-center justify-center h-12 border border-outline-variant rounded-lg hover:bg-surface-container-low transition-colors font-label-sm text-label-sm text-on-surface gap-2" type="button">
                    <span className="material-symbols-outlined">hub</span>
                    <span className='text-[15px]'>Github</span>
                </Button>
            </div>
        </>
    );
};

export default SsoOptions;
